Which statements about this TypeScript are true? Select all that apply.

```ts
type Shape =
  | { kind: "circle"; r: number }
  | { kind: "rect"; w: number;
      h: number };

function area(s: Shape): number {
  switch (s.kind) {
    case "circle":
      return Math.PI * s.r ** 2;
    case "rect":
      return s.w * s.h;
    default: {
      const gone: never = s;
      return gone;
    }
  }
}
```

